insert into public.products (id,slug,name,category,collection,price,old_price,short_description,description,details,materials,origin,heel_height,colors,sizes,images,badges,is_new,active,sort_order) values ('00000000-0000-4000-8000-000000000001','scarpin-aurora-mocha','Scarpin Aurora','scarpin','aurora',689,829,'Scarpin clássico em couro mocha com salto fino de 9cm.','O Scarpin Aurora é a tradução perfeita da elegância atemporal. Construído à mão em Franca-SP com couro legítimo italiano, apresenta um bico fino refinado e salto stiletto de 9cm que alonga a silhueta com sofisticação.',array['Cabedal em couro legítimo italiano','Forro em couro natural','Solado de couro com tira antiderrapante','Salto stiletto coberto de 9cm','Palmilha anatómica acolchoada']::text[],'Couro legítimo · Forro em couro · Solado em couro','Franca, São Paulo · Brasil','9 cm','[{"name":"Mocha","hex":"#6B4E3A"},{"name":"Cocoa","hex":"#2E1F15"},{"name":"Bone","hex":"#F5EFE6"}]'::jsonb,'[{"label":"33","stock":0},{"label":"34","stock":4},{"label":"35","stock":5},{"label":"36","stock":6},{"label":"37","stock":7},{"label":"38","stock":8},{"label":"39","stock":3},{"label":"40","stock":0}]'::jsonb,'[{"src":"https://images.unsplash.com/photo-1543163521-1bf539c55dd2?auto=format&fit=crop&w=1400&q=80","alt":"Scarpin Aurora vista frontal"},{"src":"https://images.unsplash.com/photo-1535043934128-cf0b28d52f95?auto=format&fit=crop&w=1400&q=80","alt":"Scarpin Aurora vista lateral"},{"src":"https://images.unsplash.com/photo-1581101767113-1677fc2beaa8?auto=format&fit=crop&w=1400&q=80","alt":"Scarpin Aurora detalhe"},{"src":"https://images.unsplash.com/photo-1554062614-6da4fa67725a?auto=format&fit=crop&w=1400&q=80","alt":"Scarpin Aurora composição"}]'::jsonb,array['best-seller']::text[],false,true,0) on conflict (slug) do nothing;
